	    public void AddTableTextCodes(Repository<TextCode> TextCodeRepository,Repository<Feature> FeaturesRepository,Dictionary<string, Feature> TenantFeatures,Dictionary<string, TextCode> TextCodes,IAmitalCloudContext ObjectContext,int contextTenant)
	    {  

		   		   //--------------> Additional TextCodes <--------------\\

 		   ObjectTable TarrifChargeObjectTable = ObjectContext.ObjectTables.Where(d => d.Name == "TarrifCharge" && d.Tenant == 0).FirstOrDefault(); 

 		   TextCode TarrifChargeTextCode_TarrifChargeBAddTarrifCharge = AddTextCodes.AddTextCode(new TextCodePM() { Code = "TarrifCharge.B.AddTarrifCharge", DefaultText = "Add Tariff Charge",LocalDefaultText = @"הוסף תעריף חיוב", ObjectTableId = TarrifChargeObjectTable.Id, Tenant = 0, TextCodeTypeCode = "B", IsSpellChecked = false }, TextCodeRepository, TextCodes,contextTenant);

 		   TextCode TarrifChargeTextCode_TarrifChargeBDeleteTarrifCharge = AddTextCodes.AddTextCode(new TextCodePM() { Code = "TarrifCharge.B.DeleteTarrifCharge", DefaultText = "Delete Tariff Charge",LocalDefaultText = @"מחק תעריף חיוב", ObjectTableId = TarrifChargeObjectTable.Id, Tenant = 0, TextCodeTypeCode = "B", IsSpellChecked = false }, TextCodeRepository, TextCodes,contextTenant);

